-- Original introductory lessons are real course content, separate from webhook snapshots.
CREATE TABLE english_course (
    id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    sort_order INT NOT NULL,
    title VARCHAR(200) NOT NULL,
    focus VARCHAR(200) NOT NULL,
    source VARCHAR(200) NOT NULL,
    payload JSON NOT NULL
) ENGINE=InnoDB;
CREATE TABLE english_course_progress (
    course_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    revision BIGINT NOT NULL,
    payload JSON NOT NULL,
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    FOREIGN KEY (course_id) REFERENCES english_course(id)
) ENGINE=InnoDB;
CREATE TABLE english_course_operation (
    course_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    operation CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    result JSON NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (course_id, operation),
    FOREIGN KEY (course_id) REFERENCES english_course(id)
) ENGINE=InnoDB;

INSERT INTO english_course(id,sort_order,title,focus,source,payload) VALUES('sentence-basics',1,'第一课：读懂一句话','主语、谓语、宾语与时间地点','Workbench 原创学习材料（AI 辅助编写，非真题）','{"article":{"title":"第一课：读懂一句话","text":"Every Saturday, Maya visits a small library near her home. She usually chooses a seat by the window. This morning, she brings a notebook and a bottle of water. A volunteer gives her a short story about a young doctor. Maya reads the first page slowly. She writes three useful words in her notebook. At first, she does not understand one sentence. The volunteer explains its main idea with a simple example. Maya reads it again and smiles. Before lunch, she finishes the story and tells the volunteer what she has learned.","translation":"每个星期六，玛雅都会去她家附近的一家小图书馆。她通常选择靠窗的座位。今天早上，她带来一本笔记本和一瓶水。一位志愿者给她一篇关于年轻医生的短篇故事。玛雅慢慢地读第一页。她在笔记本上写下三个有用的单词。起初，她不理解其中一个句子。志愿者用一个简单的例子解释了这句话的主要意思。玛雅又读了一遍，露出了微笑。午饭前，她读完故事，并告诉志愿者自己学到了什么。"},"sentences":[{"text":"Every Saturday, Maya visits a small library near her home.","translation":"每个星期六，玛雅都会去她家附近的一家小图书馆。","vocabulary":"visit 在这里是“去、参观”，不是名词“访问”。near her home 表示图书馆的位置。","forms":"visits ← visit；主语 Maya 是第三人称单数，一般现在时动词加 -s。","structure":"先找主干 Maya（谁）visits（做什么）a small library（去哪里）；Every Saturday 是时间状语，near her home 修饰 library。"},{"text":"A volunteer gives her a short story about a young doctor.","translation":"一位志愿者给她一篇关于年轻医生的短篇故事。","vocabulary":"give someone something = 给某人某物；about 在这里表示“关于”。","forms":"gives ← give；her 是宾格，指 Maya。","structure":"A volunteer 是主语，gives 是谓语，her 是间接宾语，a short story 是直接宾语；about a young doctor 修饰 story。"},{"text":"The volunteer explains its main idea with a simple example.","translation":"志愿者用一个简单的例子解释了这句话的主要意思。","vocabulary":"main idea = 主要意思；with 在这里表示“用、借助”。its 指上一句中那句话的。","forms":"explains ← explain；its 是物主限定词，不能与 it is 的缩写混淆。","structure":"主干是 The volunteer explains its main idea；with a simple example 说明解释的方式。"}],"words":[{"word":"visit","phonetic":null,"meaning":"去；参观","example":"Maya visits a library.","exampleTranslation":"玛雅去图书馆。"},{"word":"volunteer","phonetic":null,"meaning":"志愿者","example":"A volunteer helps Maya.","exampleTranslation":"一位志愿者帮助玛雅。"},{"word":"useful","phonetic":null,"meaning":"有用的","example":"She writes three useful words.","exampleTranslation":"她写下三个有用的单词。"},{"word":"explain","phonetic":null,"meaning":"解释","example":"He explains the main idea.","exampleTranslation":"他解释主要意思。"},{"word":"finish","phonetic":null,"meaning":"完成","example":"She finishes the story.","exampleTranslation":"她读完这个故事。"}],"questions":[{"prompt":"Maya 通常选择哪里的座位？","options":["门口","靠窗","医生旁边"],"answer":1,"explanation":"by the window 表示“靠窗”。","evidence":"She usually chooses a seat by the window."},{"prompt":"谁给 Maya 短篇故事？","options":["一位志愿者","一位医生","她的家人"],"answer":0,"explanation":"主语 A volunteer 是给予故事的人，doctor 是故事中的人物。","evidence":"A volunteer gives her a short story about a young doctor."},{"prompt":"with a simple example 在句中说明什么？","options":["解释的时间","解释的地点","解释的方式"],"answer":2,"explanation":"with 表示借助某种方式，这里是用例子解释。","evidence":"The volunteer explains its main idea with a simple example."}]}');

INSERT INTO english_course(id,sort_order,title,focus,source,payload) VALUES('word-forms',2,'第二课：单词为什么变了','过去式、过去分词与被动语态','Workbench 原创学习材料（AI 辅助编写，非真题）','{"article":{"title":"第二课：单词为什么变了","text":"Last month, our class started a small garden behind the school. We planted tomatoes and watered them every afternoon. At first, the plants grew slowly because the soil was too dry. Our teacher suggested a different watering plan. The problem was finally addressed. Since then, we have noticed several changes. The leaves have become greener, and the plants are much taller. Two broken pots were replaced yesterday. We are learning that small changes can make a difference. Next week, we will share our experience with another class and invite them to visit our garden.","translation":"上个月，我们班在学校后面开辟了一个小花园。我们种了番茄，每天下午给它们浇水。起初，因为土壤太干，植物长得很慢。老师建议采用不同的浇水计划。这个问题终于得到了解决。从那以后，我们注意到了几个变化。叶子变得更绿了，植物也高了许多。昨天，两个破花盆被换掉了。我们正逐渐认识到，小小的改变也能产生影响。下周，我们会与另一个班分享经验，并邀请他们来参观花园。"},"sentences":[{"text":"We planted tomatoes and watered them every afternoon.","translation":"我们种了番茄，每天下午给它们浇水。","vocabulary":"plant 在这里是动词“种植”；water 在这里是动词“浇水”。","forms":"planted ← plant；watered ← water；都是过去式，承接 Last month 的时间背景。","structure":"We 是主语，planted 和 watered 是由 and 连接的并列谓语；them 指 tomatoes。"},{"text":"The problem was finally addressed.","translation":"这个问题终于得到了解决。","vocabulary":"address 在这里是“处理、解决”，不是名词“地址”。","forms":"addressed ← address；这里是过去分词，was + 过去分词构成一般过去时的被动语态。","structure":"The problem 是主语，也是被处理的对象；was addressed 是谓语；finally 是副词“终于”。"},{"text":"The leaves have become greener, and the plants are much taller.","translation":"叶子变得更绿了，植物也高了许多。","vocabulary":"much 在这里修饰比较级 taller，表示高了“许多”。","forms":"leaves 是 leaf 的复数；become 在 have become 中是过去分词；greener/taller 是比较级。","structure":"and 连接两个分句：The leaves have become greener 与 the plants are much taller。"}],"words":[{"word":"plant","phonetic":null,"meaning":"种植","example":"We planted tomatoes.","exampleTranslation":"我们种了番茄。"},{"word":"water","phonetic":null,"meaning":"给……浇水","example":"We watered them every afternoon.","exampleTranslation":"我们每天下午给它们浇水。"},{"word":"address","phonetic":null,"meaning":"处理；解决","example":"The problem was addressed.","exampleTranslation":"这个问题得到了解决。"},{"word":"replace","phonetic":null,"meaning":"更换","example":"Two pots were replaced.","exampleTranslation":"两个花盆被更换了。"},{"word":"experience","phonetic":null,"meaning":"经验","example":"We will share our experience.","exampleTranslation":"我们会分享经验。"}],"questions":[{"prompt":"植物起初生长缓慢的原因是什么？","options":["土壤太干","花盆太大","没有阳光"],"answer":0,"explanation":"because 引出原因，原文明确指出土壤太干。","evidence":"At first, the plants grew slowly because the soil was too dry."},{"prompt":"was addressed 中的 addressed 是什么意思？","options":["写地址","受到致辞","被处理、解决"],"answer":2,"explanation":"结合 problem 与浇水计划的上下文，address 表示处理问题。","evidence":"The problem was finally addressed."},{"prompt":"哪件事发生在昨天？","options":["开始种番茄","更换两个破花盆","参观另一个班"],"answer":1,"explanation":"were replaced 是被动结构，yesterday 明确说明时间。","evidence":"Two broken pots were replaced yesterday."}]}');

INSERT INTO english_course(id,sort_order,title,focus,source,payload) VALUES('context-meanings',3,'第三课：熟悉单词的新含义','结合宾语和上下文理解熟词','Workbench 原创学习材料（AI 辅助编写，非真题）','{"article":{"title":"第三课：熟悉单词的新含义","text":"Leo works at a community centre on Sundays. Today, he is helping to run a reading event. Before the doors open, he checks the lights and sets several books on a table. A visitor asks whether there is a charge for joining the event. Leo explains that it is free. Later, a child points to a difficult line in a story. Leo helps her work out its meaning. Near the end, he makes a note of the visitors'' suggestions. The event runs smoothly, and Leo feels that his work has made a real difference.","translation":"利奥星期天在社区中心工作。今天，他正在帮忙组织一场阅读活动。开门前，他检查灯光，把几本书放在桌上。一位访客询问参加活动是否收费。利奥解释说，活动是免费的。后来，一个孩子指着故事里难懂的一行文字。利奥帮助她弄懂那句话的意思。临近结束时，他记下访客们的建议。活动进行得很顺利，利奥觉得自己的工作产生了实际的影响。"},"sentences":[{"text":"Today, he is helping to run a reading event.","translation":"今天，他正在帮忙组织一场阅读活动。","vocabulary":"run 在这里是“组织、运营”，不是“跑步”；run an event 要结合宾语 event 理解。","forms":"is helping 是现在进行时；to run 是不定式，run 保持原形。","structure":"主语 he，谓语 is helping；to run a reading event 说明他正在帮忙做什么。"},{"text":"A visitor asks whether there is a charge for joining the event.","translation":"一位访客询问参加活动是否收费。","vocabulary":"charge 在这里是名词“费用”，不是“充电”；下一句 free 提供了线索。","forms":"asks ← ask；joining ← join，介词 for 后使用 -ing 形式。","structure":"A visitor asks 是主句；whether 引出所询问的内容，there is 表示“有”。"},{"text":"Later, a child points to a difficult line in a story.","translation":"后来，一个孩子指着故事里难懂的一行文字。","vocabulary":"line 在这里是“一行文字”，不是队伍；points to = 指向。","forms":"points ← point；a child 是单数主语。","structure":"主干是 a child points to a difficult line；in a story 修饰 line，说明这是故事中的文字。"}],"words":[{"word":"run","phonetic":null,"meaning":"组织；运营","example":"He helps run an event.","exampleTranslation":"他帮忙组织活动。"},{"word":"charge","phonetic":null,"meaning":"费用","example":"There is no charge.","exampleTranslation":"不收费。"},{"word":"line","phonetic":null,"meaning":"一行文字","example":"Read the first line.","exampleTranslation":"读第一行。"},{"word":"note","phonetic":null,"meaning":"笔记；记录","example":"He makes a note of the suggestions.","exampleTranslation":"他记下这些建议。"},{"word":"smoothly","phonetic":null,"meaning":"顺利地","example":"The event runs smoothly.","exampleTranslation":"活动进行得很顺利。"}],"questions":[{"prompt":"run a reading event 中 run 的含义是什么？","options":["跑步","组织","流动"],"answer":1,"explanation":"run 的宾语是活动，所以这里表示组织活动。","evidence":"Today, he is helping to run a reading event."},{"prompt":"参加阅读活动需要付费吗？","options":["不需要","需要","原文未说明"],"answer":0,"explanation":"free 与上一句的 charge 呼应，说明活动免费。","evidence":"Leo explains that it is free."},{"prompt":"故事中的 line 指什么？","options":["排队的人","电话线","一行文字"],"answer":2,"explanation":"in a story 为 line 提供了语境。","evidence":"Later, a child points to a difficult line in a story."}]}');

INSERT INTO english_course(id,sort_order,title,focus,source,payload) VALUES('phrases',4,'第四课：把短语连起来看','动词短语与固定搭配','Workbench 原创学习材料（AI 辅助编写，非真题）','{"article":{"title":"第四课：把短语连起来看","text":"Our school planned a trip to a science museum on Friday. However, heavy rain was expected, so the trip was put off until Monday. Nina felt disappointed at first, but she soon came up with another idea. She invited her friends to work on a science project indoors. They looked up information about clean energy and wrote down their questions. When one experiment failed, they did not give up. They tried a simpler method and found out why the first one had not worked. By the afternoon, everyone was looking forward to sharing the results.","translation":"我们学校原计划星期五去科学博物馆。然而，预计会有大雨，因此行程被推迟到星期一。妮娜起初很失望，但很快想出了另一个主意。她邀请朋友们在室内一起做科学项目。他们查找清洁能源的资料，并写下问题。一次实验失败时，他们没有放弃。他们尝试了一种更简单的方法，并弄清了第一次失败的原因。到了下午，大家都期待着分享成果。"},"sentences":[{"text":"However, heavy rain was expected, so the trip was put off until Monday.","translation":"然而，预计会有大雨，因此行程被推迟到星期一。","vocabulary":"put off = 推迟；不能把 put 和 off 的常见词义直接拼起来。until Monday 表示到星期一。","forms":"put 的原形、过去式和过去分词形式相同；was put off 是被动结构。","structure":"so 连接原因与结果：预计有大雨 → 行程被推迟；However 表示与原计划的转折。"},{"text":"They looked up information about clean energy and wrote down their questions.","translation":"他们查找清洁能源的资料，并写下问题。","vocabulary":"look up = 查找资料；write down = 写下、记录；clean energy = 清洁能源。","forms":"looked ← look；wrote ← write，是不规则过去式。","structure":"They 是共同主语；looked up 与 wrote down 是由 and 连接的两个动作。"},{"text":"By the afternoon, everyone was looking forward to sharing the results.","translation":"到了下午，大家都期待着分享成果。","vocabulary":"look forward to = 期待；这里的 to 是介词，不是不定式标记。","forms":"was looking 是过去进行时；介词 to 后用 sharing，而不是 share。","structure":"everyone 是主语，was looking forward to 是谓语部分；sharing the results 是期待的事情。"}],"words":[{"word":"put off","phonetic":null,"meaning":"推迟","example":"The trip was put off.","exampleTranslation":"行程被推迟了。"},{"word":"come up with","phonetic":null,"meaning":"想出","example":"She came up with an idea.","exampleTranslation":"她想出了一个主意。"},{"word":"look up","phonetic":null,"meaning":"查找","example":"They looked up information.","exampleTranslation":"他们查找资料。"},{"word":"give up","phonetic":null,"meaning":"放弃","example":"They did not give up.","exampleTranslation":"他们没有放弃。"},{"word":"look forward to","phonetic":null,"meaning":"期待","example":"We look forward to sharing the results.","exampleTranslation":"我们期待分享成果。"}],"questions":[{"prompt":"博物馆行程改到了什么时候？","options":["星期五","星期日","星期一"],"answer":2,"explanation":"put off until Monday 表示推迟到星期一。","evidence":"However, heavy rain was expected, so the trip was put off until Monday."},{"prompt":"实验失败后，他们怎么做？","options":["放弃项目","尝试更简单的方法","离开学校"],"answer":1,"explanation":"他们没有放弃，而是尝试更简单的方法。","evidence":"They tried a simpler method and found out why the first one had not worked."},{"prompt":"look forward to 后面在本文中接什么形式？","options":["sharing","share","shared"],"answer":0,"explanation":"这个短语中的 to 是介词，后接动词时用 -ing 形式。","evidence":"By the afternoon, everyone was looking forward to sharing the results."}]}');

INSERT INTO english_course(id,sort_order,title,focus,source,payload) VALUES('longer-sentences',5,'第五课：拆开稍长的句子','连接词、修饰语与基础从句','Workbench 原创学习材料（AI 辅助编写，非真题）','{"article":{"title":"第五课：拆开稍长的句子","text":"When Emma moved to a new town, she found it difficult to make friends. She joined a book club that met at the local library every Wednesday. Although she was nervous, she decided to introduce herself at the first meeting. A student who sat beside her asked about her favourite books. Emma realised that they enjoyed the same stories. Because the group welcomed different opinions, she gradually became more confident. Now she often recommends books that have helped her understand other people. She believes that a small conversation can be the beginning of a lasting friendship.","translation":"埃玛搬到一个新镇子时，发现交朋友很难。她加入了一个每周三在当地图书馆聚会的读书俱乐部。虽然紧张，她还是决定在第一次聚会时介绍自己。坐在她旁边的一名学生问起她最喜欢的书。埃玛发现他们喜欢同样的故事。因为这个小组欢迎不同意见，她逐渐变得更自信了。现在，她经常推荐那些帮助她理解他人的书。她相信，一次简短的交谈可能是一段长久友谊的开始。"},"sentences":[{"text":"She joined a book club that met at the local library every Wednesday.","translation":"她加入了一个每周三在当地图书馆聚会的读书俱乐部。","vocabulary":"join a club = 加入俱乐部；meet 在这里是“聚会”。","forms":"joined ← join；met ← meet，都是过去式。","structure":"主干是 She joined a book club；that met ... 是修饰 club 的定语从句，解释这是怎样的俱乐部。"},{"text":"Although she was nervous, she decided to introduce herself at the first meeting.","translation":"虽然紧张，她还是决定在第一次聚会时介绍自己。","vocabulary":"although = 虽然；decide to do = 决定做；introduce herself = 自我介绍。","forms":"decided ← decide；herself 是与 she 对应的反身代词；to introduce 中动词用原形。","structure":"先看主句 she decided to introduce herself；Although she was nervous 是让步状语从句，表示尽管存在的情况。"},{"text":"A student who sat beside her asked about her favourite books.","translation":"坐在她旁边的一名学生问起她最喜欢的书。","vocabulary":"beside = 在……旁边；ask about = 询问关于……的情况。","forms":"sat ← sit；asked ← ask。","structure":"主干是 A student asked about her favourite books；who sat beside her 修饰 student，不要把 asked 误当作从句的一部分。"}],"words":[{"word":"join","phonetic":null,"meaning":"加入","example":"She joined a book club.","exampleTranslation":"她加入了读书俱乐部。"},{"word":"although","phonetic":null,"meaning":"虽然","example":"Although she was nervous, she spoke.","exampleTranslation":"虽然紧张，她还是开口了。"},{"word":"introduce","phonetic":null,"meaning":"介绍","example":"She introduced herself.","exampleTranslation":"她介绍了自己。"},{"word":"confident","phonetic":null,"meaning":"自信的","example":"She became more confident.","exampleTranslation":"她变得更自信了。"},{"word":"recommend","phonetic":null,"meaning":"推荐","example":"She recommends useful books.","exampleTranslation":"她推荐有用的书。"}],"questions":[{"prompt":"读书俱乐部什么时候聚会？","options":["每周三","每周五","每天"],"answer":0,"explanation":"that met ... 修饰俱乐部，其中 every Wednesday 给出聚会时间。","evidence":"She joined a book club that met at the local library every Wednesday."},{"prompt":"Although she was nervous 与后半句是什么关系？","options":["因果","并列","让步"],"answer":2,"explanation":"虽然紧张，仍然决定介绍自己，although 表示让步。","evidence":"Although she was nervous, she decided to introduce herself at the first meeting."},{"prompt":"who sat beside her 修饰谁？","options":["最喜欢的书","一名学生","埃玛住的小镇"],"answer":1,"explanation":"who 引导的定语从句紧跟 A student，说明是哪一位学生。","evidence":"A student who sat beside her asked about her favourite books."}]}');
